use schemars::JsonSchema;
use serde::Serialize;

/// Machine-readable mirror of the language reference. Generated by `dump-card`
/// and consumed by language-card stability/coverage tests, MCP tooling, and
/// the eventual `--explain` flag.
#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct LanguageCard {
    pub version: String,
    pub schema_version: u32,
    pub keywords: Vec<String>,
    pub operators: Vec<Operator>,
    pub types: Vec<TypeEntry>,
    pub builtins: Vec<BuiltinEntry>,
    pub error_codes: Vec<ErrorCodeEntry>,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct Operator {
    pub token: String,
    pub name: String,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct TypeEntry {
    pub name: String,
    pub llvm: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub params: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub forms: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub note: Option<String>,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct BuiltinEntry {
    pub name: String,
    pub parameters: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub returns: Option<String>,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct ErrorCodeEntry {
    pub code: String,
    pub name: String,
    pub fields: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub hint: Option<String>,
}

use crate::analyzer::builtins::BUILTIN_FUNCTIONS;
use crate::diagnostics::codes::ALL_CODES;

pub fn build_language_card() -> LanguageCard {
    let mut keywords = vec![
        "arr", "bool", "break", "char", "continue", "discord", "else", "false",
        "float", "fnord", "for", "if", "in", "int", "mut", "return", "str",
        "true", "while",
    ]
    .into_iter()
    .map(String::from)
    .collect::<Vec<_>>();
    keywords.sort();

    let mut operators: Vec<Operator> = vec![
        ("+",  "Plus"), ("-",  "Minus"), ("*",  "Multiply"), ("/",  "Divide"),
        ("%",  "Modulo"), (":=", "DeclareAssign"), ("=",  "Assign"),
        ("==", "Equal"), ("!=", "NotEqual"),
        ("<",  "LessThan"), ("<=", "LessEqual"), (">",  "GreaterThan"), (">=", "GreaterEqual"),
        ("&&", "And"), ("||", "Or"), ("!",  "Not"),
        ("&",  "BitAnd"), ("|",  "BitOr"), ("^",  "Caret"), ("~",  "Tilde"),
        ("<<", "Shl"), (">>", "Shr"),
        ("..", "DotDot"),
    ]
    .into_iter()
    .map(|(token, name)| Operator { token: token.into(), name: name.into() })
    .collect();
    operators.sort_by(|a, b| a.token.cmp(&b.token));

    let types = vec![
        TypeEntry {
            name: "int".into(),    llvm: "i64".into(),
            params: None, forms: None, note: None,
        },
        TypeEntry {
            name: "bool".into(),   llvm: "i1".into(),
            params: None, forms: None, note: None,
        },
        TypeEntry {
            name: "char".into(),   llvm: "i8".into(),
            params: None, forms: None, note: None,
        },
        TypeEntry {
            name: "float".into(),  llvm: "f64".into(),
            params: None, forms: None, note: None,
        },
        TypeEntry {
            name: "str".into(),    llvm: "ptr".into(),
            params: None, forms: None,
            note: Some("null-terminated C string; slice representation in Tier 2".into()),
        },
        TypeEntry {
            name: "arr".into(),    llvm: "[N x T]".into(),
            params: Some(vec!["T".into()]), forms: None,
            note: Some("fixed-size; element type tracked, size inferred from literal".into()),
        },
        TypeEntry {
            name: "&T".into(),     llvm: "ptr".into(),
            params: None,
            forms: Some(vec!["&T".into(), "&mut T".into()]),
            note: Some("Tier 1 restricts pointee to 'int' until Tier 2 slice work".into()),
        },
    ];

    let mut builtins: Vec<BuiltinEntry> = BUILTIN_FUNCTIONS
        .iter()
        .map(|b| BuiltinEntry {
            name: b.name.to_string(),
            parameters: b.parameters.iter().map(|t| t.to_string()).collect(),
            returns: b.return_type.as_ref().map(|t| t.to_string()),
        })
        .collect();
    builtins.push(BuiltinEntry {
        name: "len".into(),
        parameters: vec!["arr".into()],
        returns: Some("int".into()),
    });
    builtins.sort_by(|a, b| a.name.cmp(&b.name));

    let mut error_codes: Vec<ErrorCodeEntry> = ALL_CODES
        .iter()
        .map(|(code, code_str)| ErrorCodeEntry {
            code: code_str.to_string(),
            name: code.name().to_string(),
            fields: code.fields().iter().map(|f| f.to_string()).collect(),
            hint: code.static_hint().map(String::from),
        })
        .collect();
    error_codes.sort_by(|a, b| a.code.cmp(&b.code));

    LanguageCard {
        version: env!("CARGO_PKG_VERSION").to_string(),
        schema_version: 1,
        keywords,
        operators,
        types,
        builtins,
        error_codes,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn card_includes_known_keyword() {
        let card = build_language_card();
        assert!(
            card.keywords.iter().any(|k| k == "while"),
            "expected 'while' in keywords, got {:?}", card.keywords
        );
    }

    #[test]
    fn card_includes_known_type() {
        let card = build_language_card();
        assert!(
            card.types.iter().any(|t| t.name == "int" && t.llvm == "i64"),
            "expected int → i64 mapping in types"
        );
    }

    #[test]
    fn card_includes_known_builtin() {
        let card = build_language_card();
        assert!(card.builtins.iter().any(|b| b.name == "print_int"));
        assert!(card.builtins.iter().any(|b| b.name == "len"));
    }

    #[test]
    fn card_includes_all_error_codes() {
        let card = build_language_card();
        assert_eq!(
            card.error_codes.len(),
            crate::diagnostics::codes::ALL_CODES.len(),
            "card error_codes count must equal ALL_CODES count"
        );
        assert!(card.error_codes.iter().any(|e| e.code == "E0203" && e.name == "TypeMismatch"));
    }

    #[test]
    fn card_entries_are_sorted_deterministically() {
        let card = build_language_card();
        let mut sorted = card.keywords.clone();
        sorted.sort();
        assert_eq!(card.keywords, sorted, "keywords must be sorted alphabetically");

        let codes: Vec<_> = card.error_codes.iter().map(|e| e.code.clone()).collect();
        let mut sorted_codes = codes.clone();
        sorted_codes.sort();
        assert_eq!(codes, sorted_codes, "error_codes must be sorted by code");
    }
}
